<template>
  <main class="app-shell">
    <AuthenticatedTopbar :user="user" section="collections" />
    <div v-if="activeConfirm" class="modal-backdrop" @click.self="chooseConfirm(false)"><section class="modal-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">CONFIRM</p><h2>{{ t('common.confirm') }}</h2></div><button class="icon-button" :title="t('common.close')" @click="chooseConfirm(false)"><X :size="18" /></button></div><p class="modal-copy">{{ activeConfirm.message }}</p><div class="modal-actions"><button class="secondary-button" @click="chooseConfirm(false)">{{ t('common.cancel') }}</button><button class="secondary-button danger-action" @click="chooseConfirm(true)">{{ t('common.confirm') }}</button></div></section></div>
    <section class="content-wrap">
      <div class="page-heading"><div><p class="eyebrow">WORKSPACE / COLLECTIONS</p><h1>{{ t('page.collections') }}</h1><p class="muted">{{ t('collections.copy') }}</p></div><div class="sync-heading-actions"><button class="secondary-button" :title="t('files.refresh')" @click="loadCollections"><RefreshCw :size="16" :class="{ spin: collectionsLoading }" /></button><button class="primary-button" @click="openCollectionCreate"><UploadCloud :size="17" /> {{ t('collection.create') }}</button></div></div>
      <div v-if="error" class="alert error">{{ error }}</div><div v-if="collectionNotice" class="alert success">{{ collectionNotice }}</div>

      <section class="collection-section"><div class="collection-section-header"><h2>{{ t('collection.my') }}</h2></div><div v-if="collectionsLoading" class="empty-state"><LoaderCircle :size="24" class="spin" /></div><div v-else-if="!collections.length" class="transfers-empty">{{ t('collection.noCollections') }}</div><div v-else class="collection-grid"><article v-for="item in collections" :key="item.id" class="collection-row"><strong>{{ item.name }}</strong><small>{{ item.uploadCount }} / {{ item.maxUploads || t('collection.unlimited') }}</small><span v-if="item.passwordProtected" class="protected-mark" :title="t('collection.passwordProtectedBadge')"><Lock :size="13" /> {{ t('collection.passwordProtectedBadge') }}</span><span class="status-label" :class="{ disabled: item.status !== 'active' }"><i></i>{{ collectionStatusLabel(item) }}</span><div class="collection-row-actions"><button class="icon-text-button" @click="viewCollection(item)"><Eye :size="15" /> {{ t('collection.viewFiles') }}</button><button class="icon-button" :title="t('collection.copy')" @click="copyCollection(item)"><Copy :size="15" /></button><button v-if="item.status === 'active'" class="icon-button" :title="t('collection.edit')" @click="openCollectionEdit(item)"><Pencil :size="15" /></button><button v-if="item.status === 'active'" class="icon-button danger-icon" :title="t('collection.revoke')" @click="revokeCollection(item)"><Trash2 :size="15" /></button></div><a class="collection-link" :href="absoluteCollectionUrl(item)" target="_blank" rel="noopener">{{ absoluteCollectionUrl(item) }}</a><div v-if="collectionDetails?.id === item.id" class="collection-files"><div v-if="!collectionDetails.files?.length">{{ t('collection.noCollections') }}</div><div v-for="received in collectionDetails.files" :key="received.id" class="collection-file"><strong>{{ received.originalName }}</strong><span v-if="received.remark">{{ t('collection.remark') }}: {{ received.remark }}</span><small>{{ formatDate(received.createdAt) }}</small></div></div></article></div></section><div v-if="collectionsTotal > collectionsPageSize" class="pagination"><button class="secondary-button" :disabled="collectionsPage === 1" @click="collectionsPage--; loadCollections()">{{ t('common.previous') }}</button><span>{{ t('common.page', { page: collectionsPage }) }} / {{ collectionsTotalPages }}</span><button class="secondary-button" :disabled="collectionsPage * collectionsPageSize >= collectionsTotal" @click="collectionsPage++; loadCollections()">{{ t('common.next') }}</button><label class="page-size-label">{{ t('common.pageSize') }}<select v-model.number="collectionsPageSize" @change="changeCollectionsPageSize"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><template v-if="collectionsTotalPages > 7"><input v-model="collectionsPageInput" class="jump-input" type="number" min="1" :max="collectionsTotalPages" :placeholder="t('common.pageInput')" @keyup.enter="jumpCollectionsPage" /><button class="secondary-button" @click="jumpCollectionsPage">{{ t('common.jump') }}</button></template></div>
      <BrandFooter />
    </section>

    <div v-if="collectionCreateOpen" class="modal-backdrop" @click.self="collectionCreateOpen = false"><section class="modal-panel share-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ editingCollection ? t('collection.editTitle') : t('collection.create') }}</p><h2>{{ editingCollection ? (collectionForm.name || t('collection.editTitle')) : t('collection.createTitle') }}</h2></div><button class="icon-button" :title="t('common.close')" @click="collectionCreateOpen = false"><X :size="18" /></button></div><form @submit.prevent="saveCollection"><label class="form-label">{{ t('collection.name') }}<input v-model.trim="collectionForm.name" maxlength="255" required /></label><label v-if="!editingCollection" class="form-label">{{ t('collection.expiresInHours') }}<input v-model.number="collectionForm.expiresInHours" type="number" min="1" required /></label><label v-else class="form-label">{{ t('collection.expiresAtEdit') }}<input v-model="collectionForm.expiresAtLocal" type="datetime-local" required /></label><label class="form-label">{{ t('collection.maxUploads') }}<input v-model.number="collectionForm.maxUploads" type="number" min="0" required /></label><label class="form-label">{{ t('collection.maxFileBytesMB') }}<input v-model.number="collectionForm.maxFileBytesMB" type="number" min="0" required /></label><fieldset class="form-fieldset"><legend>{{ t('collection.passwordModeLabel') }}</legend><div class="collection-mode-options"><label v-for="mode in passwordModes" :key="mode.value" class="mode-option"><input v-model="collectionForm.passwordMode" type="radio" :value="mode.value" /><span>{{ t(mode.key) }}</span></label></div><label v-if="collectionForm.passwordMode === 'manual'" class="form-label">{{ t('collection.passwordManual') }}<input v-model="collectionForm.manualPassword" type="text" maxlength="72" autocomplete="new-password" :placeholder="t('collection.passwordManualPlaceholder')" /></label><p v-if="collectionForm.passwordMode === 'random'" class="mode-hint">{{ t('collection.passwordRandomHint') }}</p><p v-else-if="collectionForm.passwordMode === 'none' && !editingCollection" class="mode-hint">{{ t('collection.passwordNoneHint') }}</p></fieldset><p v-if="collectionError" class="alert error">{{ collectionError }}</p><button class="primary-button submit-button" :disabled="collectionSaving"><span>{{ collectionSaving ? t('common.loading') : (editingCollection ? t('collection.saved') : t('collection.create')) }}</span><UploadCloud :size="17" /></button></form></section></div>
    <div v-if="collectionResult" class="modal-backdrop" @click.self="collectionResult = null"><section class="modal-panel share-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ t('collection.create') }}</p><h2>{{ collectionResult.name }}</h2></div><button class="icon-button" :title="t('common.close')" @click="collectionResult = null"><X :size="18" /></button></div><template v-if="collectionResult.password"><div class="one-time-secret"><p class="eyebrow">{{ t('collection.passwordOneTimeLabel') }}</p><div class="share-url secret-value"><input :value="collectionResult.password" readonly /><button type="button" class="icon-button" :title="t('collection.copyPassword')" @click="copyText(collectionResult.password).then(ok => { collectionNotice = ok ? t('collection.passwordCopied') : t('collection.copyFailed') })"><Copy :size="16" /></button></div><p class="alert info">{{ t('collection.passwordOneTimeNotice') }}</p></div><label class="form-label">{{ t('collection.passwordConvenienceLabel') }}<div class="share-url"><input :value="absolutePasswordUrl(collectionResult)" readonly /><button type="button" class="icon-button" :title="t('collection.copy')" @click="copyText(absolutePasswordUrl(collectionResult)).then(ok => { collectionNotice = ok ? t('collection.copied') : t('collection.copyFailed') })"><Copy :size="16" /></button></div></label></template><label class="form-label">{{ t('collection.link') }}<div class="share-url"><input :value="absoluteCollectionUrl(collectionResult)" readonly /><button type="button" class="icon-button" :title="t('collection.copy')" @click="copyText(absoluteCollectionUrl(collectionResult)).then(ok => { collectionNotice = ok ? t('collection.copied') : t('collection.copyFailed') })"><Copy :size="16" /></button></div></label><p v-if="collectionNotice" class="alert success">{{ collectionNotice }}</p></section></div>
  </main>
</template>

<script setup>
// CollectionsView 是"我的收集"独立页面（v014 #7）：复用文件页的收集管理逻辑
// （列表/创建/编辑/撤销/复制链接/已收文件），并带独立顶栏与路由 /collections。
// CollectionsView is the standalone "My collections" page (v014 #7): it reuses the file page's
// collection-management logic (list/create/edit/revoke/copy-link/received files) with its own
// topbar and the /collections route.
import { computed, onMounted, ref } from 'vue'
import { api } from '../api'
import AuthenticatedTopbar from '../components/AuthenticatedTopbar.vue'
import BrandFooter from '../components/BrandFooter.vue'
import { currentLocale, t } from '../i18n'
import { Copy, Eye, LoaderCircle, Lock, Pencil, RefreshCw, Trash2, UploadCloud, X } from 'lucide-vue-next'

const user = ref(JSON.parse(localStorage.getItem('filebox_user') || '{}'))
const collections = ref([]); const collectionsLoading = ref(false); const collectionCreateOpen = ref(false); const collectionSaving = ref(false); const collectionError = ref(''); const collectionNotice = ref(''); const collectionResult = ref(null); const collectionDetails = ref(null); const editingCollection = ref(false); const collectionForm = ref({ name: '', expiresInHours: 24, maxUploads: 0, maxFileBytesMB: 0, expiresAtLocal: '', passwordMode: 'random', manualPassword: '' }); const error = ref('')
const collectionsPage = ref(1); const collectionsTotal = ref(0); const collectionsPageSize = ref(Number(localStorage.getItem('filebox_pagesize_collections')) || 20); const collectionsPageInput = ref(''); const confirmQueue = ref([])
const passwordModes = computed(() => editingCollection.value
  ? [{ value: 'keep', key: 'collection.passwordModeKeep' }, { value: 'random', key: 'collection.passwordModeRandom' }, { value: 'manual', key: 'collection.passwordModeManual' }, { value: 'none', key: 'collection.passwordModeNone' }]
  : [{ value: 'random', key: 'collection.passwordModeRandom' }, { value: 'manual', key: 'collection.passwordModeManual' }, { value: 'none', key: 'collection.passwordModeNone' }])

async function loadCollections() { collectionsLoading.value = true; try { const body = await api(`/api/collections?page=${collectionsPage.value}&pageSize=${collectionsPageSize.value}`); collections.value = body.data.items || []; collectionsTotal.value = body.data.total || 0 } catch (err) { error.value = err.message } finally { collectionsLoading.value = false } }
// 收集分页辅助（v018 #7）：pageSize 选择 + 页码跳转。
// Collections pagination helpers (v018 #7): page-size selection and page jumping.
const collectionsTotalPages = computed(() => Math.max(1, Math.ceil(collectionsTotal.value / collectionsPageSize.value)))
function changeCollectionsPageSize() { collectionsPage.value = 1; localStorage.setItem('filebox_pagesize_collections', String(collectionsPageSize.value)); loadCollections() }
function jumpCollectionsPage() { const target = Number(collectionsPageInput.value); if (!target || target < 1 || target > collectionsTotalPages.value) { collectionsPageInput.value = ''; return } collectionsPage.value = target; collectionsPageInput.value = ''; loadCollections() }
function openCollectionCreate() { editingCollection.value = false; collectionCreateOpen.value = true; collectionResult.value = null; collectionError.value = ''; collectionNotice.value = ''; collectionForm.value = { name: '', expiresInHours: 24, maxUploads: 0, maxFileBytesMB: 0, expiresAtLocal: '', passwordMode: 'random', manualPassword: '' } }
function toLocalInputValue(value) { const date = new Date(value); if (Number.isNaN(date.getTime())) return ''; const pad = num => String(num).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}` }
function absoluteCollectionUrl(item) { return item?.url ? new URL(item.url, window.location.origin).href : '' }
function absolutePasswordUrl(item) { return item?.passwordUrl ? new URL(item.passwordUrl, window.location.origin).href : '' }
function openCollectionEdit(item) { editingCollection.value = true; collectionCreateOpen.value = true; collectionResult.value = null; collectionError.value = ''; collectionNotice.value = ''; collectionForm.value = { _id: item.id, name: item.name || '', expiresInHours: 24, maxUploads: item.maxUploads || 0, maxFileBytesMB: item.maxFileBytes ? Math.round(item.maxFileBytes / 1024 / 1024 * 100) / 100 : 0, expiresAtLocal: toLocalInputValue(item.expiresAt), passwordMode: 'keep', manualPassword: '' } }
// saveCollection creates or updates a collection: edit mode submits an absolute expiry converted to UTC.
// 创建/编辑统一携带 passwordMode；manual 模式才附带 password（创建默认 random，编辑默认 keep）。
async function saveCollection() { collectionSaving.value = true; collectionError.value = ''; try { const payload = { name: collectionForm.value.name, maxUploads: collectionForm.value.maxUploads, maxFileBytes: Math.round(collectionForm.value.maxFileBytesMB * 1024 * 1024), passwordMode: collectionForm.value.passwordMode }; if (collectionForm.value.passwordMode === 'manual') { const manual = collectionForm.value.manualPassword || ''; if (!manual.trim()) throw new Error(t('collection.passwordManualRequired')); payload.password = manual } let body; if (editingCollection.value) { body = await api(`/api/collections/${collectionForm.value._id}`, { method: 'PUT', body: JSON.stringify({ ...payload, expiresAt: new Date(collectionForm.value.expiresAtLocal).toISOString() }) }) } else { body = await api('/api/collections', { method: 'POST', body: JSON.stringify({ ...payload, expiresInHours: collectionForm.value.expiresInHours }) }) } if (body.data?.password || body.data?.passwordUrl) { collectionResult.value = body.data } else if (editingCollection.value) { collectionNotice.value = t('collection.saved') } else { collectionResult.value = body.data } collectionCreateOpen.value = false; await loadCollections() } catch (err) { collectionError.value = err.message } finally { collectionSaving.value = false } }
async function copyText(value) { try { await navigator.clipboard.writeText(value); return true } catch { return false } }
async function copyCollection(item) { const ok = await copyText(absoluteCollectionUrl(item)); collectionNotice.value = ok ? t('collection.copied') : t('collection.copyFailed') }
function remainingLabel(item) { if (!item.remainingSeconds) return `${t('collection.remaining')}: 0`; const hours = Math.floor(item.remainingSeconds / 3600); const minutes = Math.max(1, Math.floor(item.remainingSeconds / 60)); return `${t('collection.remaining')}: ${hours ? `${hours}h` : `${minutes}m`}` }
function collectionStatusLabel(item) { const label = item.status === 'expired' ? t('collection.expired') : item.status === 'revoked' ? t('collection.revoked') : item.status === 'limit_reached' ? t('collection.limitReached') : t('collection.active'); return `${label} · ${remainingLabel(item)}` }
async function viewCollection(item) { if (collectionDetails.value?.id === item.id) { collectionDetails.value = null; return } try { const body = await api(`/api/collections/${item.id}`); collectionDetails.value = body.data } catch (err) { error.value = err.message } }
function askConfirm(message) {
  return new Promise(resolve => {
    const entry = { message, resolve }
    entry.timer = setTimeout(() => {
      const position = confirmQueue.value.indexOf(entry)
      if (position >= 0) confirmQueue.value.splice(position, 1)
      resolve(false)
    }, 60000)
    confirmQueue.value.push(entry)
  })
}
const activeConfirm = computed(() => confirmQueue.value[0] || null)
function chooseConfirm(value) {
  const entry = confirmQueue.value.shift()
  if (!entry) return
  clearTimeout(entry.timer)
  entry.resolve(Boolean(value))
}
async function revokeCollection(item) { if (!(await askConfirm(t('collection.confirmRevoke')))) return; try { await api(`/api/collections/${item.id}`, { method: 'DELETE' }); collectionNotice.value = t('collection.revoked'); await loadCollections() } catch (err) { error.value = err.message } }
function formatDate(value) { return value ? new Date(value).toLocaleString(currentLocale.value === 'en' ? 'en-US' : currentLocale.value, { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-' }
onMounted(loadCollections)
</script>
